def can_complete(row, tenant, owner, fence, now):
    if not isinstance(row, dict):
        return False
    if not isinstance(tenant, str) or not isinstance(owner, str):
        return False
    if not isinstance(fence, int) or isinstance(fence, bool):
        return False
    if not isinstance(now, int) or isinstance(now, bool):
        return False
    required = ("tenant", "state", "owner", "fence", "lease_until")
    if any(key not in row for key in required):
        return False
    if not isinstance(row["tenant"], str) or not isinstance(row["owner"], str):
        return False
    if not isinstance(row["fence"], int) or isinstance(row["fence"], bool):
        return False
    if not isinstance(row["lease_until"], int) or isinstance(row["lease_until"], bool):
        return False
    return (row["state"] == "running"
            and row["tenant"] == tenant
            and row["owner"] == owner
            and row["fence"] == fence
            and row["lease_until"] > now)
